n, m, k = map(int, input().split())
to = [[] for i in range(n + 2)]
for i in range(m):
    x, y = map(int, input().split())
    to[x].append(y)
    to[y].append(x)
f = [[[False] * (n + 2) for _ in range(n + 2)] for __ in range(k + 2)]
for i in range(1, n + 1):
    f[0][i][i] = True
for t in range(1, k + 1):
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            if f[t - 1][x][y]:
                for z in to[y]:
                    f[t][x][z] = True
for i in range(1, n + 1):
    Ans = []
    for t in range(1, k + 1):
        ans = 0
        for j in range(1, n + 1):
            ans += (f[t][i][j] == True)
        Ans.append(str(ans))
    print(' '.join(Ans))
